import { useCallback, useEffect, useState } from 'react'
import type { FieldErrors, NewExpense } from '../../application/ExpenseGateway'
import type { ExpenseViewModel } from '../../application/ExpenseViewModel'
import { useExpensesUseCases } from '../useExpensesUseCases/useExpensesUseCases'

export const useExpenses = () => {
  const { listExpenses, submitExpense } = useExpensesUseCases()
  const [expenses, setExpenses] = useState<ExpenseViewModel[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const load = useCallback(async () => {
    try {
      setExpenses(await listExpenses.execute())
      setError(null)
    } catch (e) {
      setError(e instanceof Error ? e.message : 'Could not load expenses')
    } finally {
      setLoading(false)
    }
  }, [listExpenses])

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    void load()
  }, [load])

  const submit = useCallback(
    async (expense: NewExpense): Promise<FieldErrors> => {
      try {
        const result = await submitExpense.execute(expense)
        if (!result.ok) return result.errors
        await load()
        return {}
      } catch (e) {
        return { form: e instanceof Error ? e.message : 'Could not submit expense' }
      }
    },
    [submitExpense, load],
  )

  return { expenses, loading, error, submit }
}
